// Messages
pub fn show_sexp(e: &'static Sexp) -> Str {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(s) => {
            s
        }
        Sexp::Str(s) => {
            string_append(str_lit("\""), string_append(s, str_lit("\"")))
        }
        Sexp::Num(k, num_file, num_pos) => {
            i64_to_string(k)
        }
        Sexp::Big(text, f, p) => {
            text
        }
        Sexp::Chr(c) => {
            string_append(str_lit("#\\"), char_to_string(c))
        }
        Sexp::Real(t) => {
            t
        }
        Sexp::Lst(xs, src_file, src_line, src_pos) => {
            string_append(str_lit("("), string_append(show_sexps(xs), str_lit(")")))
        }
    }
}

pub fn show_sexps(xs: Sexps) -> Str {
    if null_p(xs) {
        str_lit("")
    } else if null_p(cdr(xs)) {
        show_sexp(car(xs))
    } else {
        string_append(show_sexp(car(xs)), string_append(str_lit(" "), show_sexps(cdr(xs))))
    }
}

pub fn cv_where(v: &'static Cv) -> Str {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, r#as, es, here, group, file, line, fs, tv, at) => {
            here
        }
    }
}

/// An error, said where: the innermost list being checked, and the
/// definition.
pub fn refuse(v: &'static Cv, message: Str) -> ! {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, r#as, es, here, group, file, line, fs, tv, at) => {
            error(string_append(str_lit("kfx: "), string_append(if i64_eq(line, 0i64) {
                str_lit("")
            } else {
                string_append(file, string_append(str_lit(":"), string_append(i64_to_string(line), str_lit(": "))))
            }, string_append(str_lit("in "), string_append(here, string_append(str_lit(": "), message))))))
        }
    }
}

/// A name, where one is expected: refused, saying where, if `e` is none.
pub fn name_of(v: &'static Cv, e: &'static Sexp) -> Str {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(s) => {
            s
        }
        _ => {
            let other = tagcase_;
            refuse(v, string_append(str_lit("a name is expected here, not "), show_sexp(other)))
        }
    }
}

// Effects
pub fn take_chars(cs: List<char>, n: i64) -> List<char> {
    if (null_p(cs) || i64_eq(n, 0i64)) {
        nil()
    } else {
        cons(car(cs), take_chars(cdr(cs), i64_minus(n, 1i64)))
    }
}

pub fn substring_of(x: Str, n: i64) -> Str {
    list_to_string(take_chars(string_to_list(x), n))
}

pub fn has_prefix_p(x: Str, p: Str) -> bool {
    (not(i64_lt(string_length_i64(x), string_length_i64(p))) && string_eq_p(substring_of(x, string_length_i64(p)), p))
}

pub fn drop_chars(mut cs: List<char>, mut n: i64) -> List<char> {
    loop {
        if (null_p(cs) || i64_eq(n, 0i64)) {
            return cs;
        } else {
            (cs, n) = (cdr(cs), i64_minus(n, 1i64));
            continue;
        }
    }
}

pub fn after_prefix(x: Str, p: Str) -> Str {
    list_to_string(drop_chars(string_to_list(x), string_length_i64(p)))
}

pub fn strings_eq_p(a: Strings, b: Strings) -> bool {
    if null_p(a) {
        null_p(b)
    } else if null_p(b) {
        false
    } else {
        (string_eq_p(car(a), car(b)) && strings_eq_p(cdr(a), cdr(b)))
    }
}

/// A product's label or a sum's tag, as written: a name or a number.
pub fn label_of(e: &'static Sexp) -> Str {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(n) => {
            n
        }
        Sexp::Num(k, f, p) => {
            i64_to_string(k)
        }
        _ => {
            let other = tagcase_;
            str_lit("")
        }
    }
}

/// Whether effect `es` may abort: a `goto` on some region. Such a
/// procedure, in Rust, returns a `Result` (emit.kfx).
pub fn escapes_p(es: Strings) -> bool {
    any_p(lambda1(move |x: Str| {
        (i64_gt(string_length_i64(x), 5i64) && string_eq_p(substring_of(x, 5i64), str_lit("goto:")))
    }), es)
}

/// An effect on `acyclic`: making and reading frozen data are pure, in
/// FX-26; writing it is refused where its type is read.
pub fn frozen_atom_p(x: Str) -> bool {
    (string_eq_p(x, str_lit("read:acyclic")) || string_eq_p(x, str_lit("alloc:acyclic")) || string_eq_p(x, str_lit("write:acyclic")))
}

pub fn effs_union(mut a: Strings, mut b: Strings) -> Strings {
    loop {
        if null_p(a) {
            if any_p(lambda1(move |x: Str| {
                frozen_atom_p(x)
            }), b) {
                (a, b) = (b, nil());
                continue;
            } else {
                return b;
            }
        } else if (frozen_atom_p(car(a)) || string_member_p(car(a), b)) {
            a = cdr(a);
            continue;
        } else {
            (a, b) = (cdr(a), cons(car(a), b));
            continue;
        }
    }
}

/// A read of one global, `g:name`; not a `goto:`.
pub fn global_atom_p(x: Str) -> bool {
    (i64_gt(string_length_i64(x), 1i64) && char_eq_p(string_ref_i64(x, 0i64), 'g') && char_eq_p(string_ref_i64(x, 1i64), ':'))
}

/// Whether effect `a` is within `b`: a read of one global is within a
/// read of all of them.
pub fn effs_within_p(a: Strings, b: Strings) -> bool {
    (null_p(a) || ((string_member_p(car(a), b) || (global_atom_p(car(a)) && string_member_p(str_lit("@globals"), b))) && effs_within_p(cdr(a), b)))
}

pub fn words_of(xs: Strings) -> Str {
    if null_p(xs) {
        str_lit("")
    } else if null_p(cdr(xs)) {
        car(xs)
    } else {
        string_append(car(xs), string_append(str_lit(" "), words_of(cdr(xs))))
    }
}

pub fn show_effs(es: Strings) -> Str {
    if null_p(es) {
        str_lit("pure")
    } else {
        string_append(str_lit("("), string_append(words_of(es), str_lit(")")))
    }
}

pub fn find_effdef(mut v: &'static Cv, mut name: Str, mut es: Effdefs) -> Strings {
    loop {
        if null_p(es) {
            return refuse(v, string_append(str_lit("an effect KFX does not have: "), name));
        } else {
            let tagcase_ = car(es);
            match *tagcase_ {
                Effdef::Effdef(n, atoms) => {
                    if string_eq_p(n, name) {
                        return atoms;
                    } else {
                        es = cdr(es);
                        continue;
                    }
                }
            }
        }
    }
}

pub fn cv_effdefs(v: &'static Cv) -> Effdefs {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, r#as, es, here, group, file, line, fs, tv, at) => {
            es
        }
    }
}

/// A region's name: a constant, `@a`, or a poly's region binder, `'r`.
pub fn region_name(v: &'static Cv, tvars: Strings, r: &'static Sexp) -> Str {
    let s = {
        let tagcase_ = r;
        match *tagcase_ {
            Sexp::Sym(n) => {
                n
            }
            _ => {
                let other = tagcase_;
                refuse(v, string_append(str_lit("a region KFX does not have: "), show_sexp(other)))
            }
        }
    };
    if string_eq_p(s, str_lit("@globals")) {
        refuse(v, str_lit("globals are a region only in effects: (read @globals), (read (globals g))"))
    } else if char_eq_p(string_ref_i64(s, 0i64), '@') {
        s
    } else if string_eq_p(s, str_lit("acyclic")) {
        s
    } else if string_member_p(string_append(str_lit("'"), s), tvars) {
        string_append(str_lit("'"), s)
    } else {
        refuse(v, string_append(str_lit("a region KFX-0 does not have: "), s))
    }
}

pub fn parse_region(v: &'static Cv, tvars: Strings, r: &'static Sexp) -> &'static Ty {
    let name = region_name(v, tvars, r);
    if char_eq_p(string_ref_i64(name, 0i64), '\'') {
        ty_var(name)
    } else {
        ty_rconst(name)
    }
}

/// The region of data that may be written: not `acyclic`, which is frozen.
pub fn parse_mutable_region(v: &'static Cv, tvars: Strings, r: &'static Sexp) -> &'static Ty {
    if sym_is_p(r, str_lit("acyclic")) {
        refuse(v, str_lit("mutable data at acyclic, which is frozen and never written"))
    } else {
        parse_region(v, tvars, r)
    }
}

pub fn parse_effect(v: &'static Cv, tvars: Strings, e: &'static Sexp) -> Strings {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(s) => {
            if string_eq_p(s, str_lit("pure")) {
                nil()
            } else if string_eq_p(s, str_lit("spin")) {
                cons(str_lit("spin"), nil())
            } else {
                find_effdef(v, s, cv_effdefs(v))
            }
        }
        Sexp::Lst(xs, src_file, src_line, src_pos) => {
            if sym_is_p(car(xs), str_lit("maxeff")) {
                parse_effects(v, tvars, cdr(xs))
            } else if (sym_is_p(car(xs), str_lit("read")) && sym_is_p(second(xs), str_lit("@globals"))) {
                cons(str_lit("@globals"), nil())
            } else if (sym_is_p(car(xs), str_lit("read")) && head_is_p(second(xs), str_lit("globals"))) {
                map(lambda1(move |g: &'static Sexp| {
                    string_append(str_lit("g:"), name_of(v, g))
                }), cdr(items(second(xs))))
            } else if sym_is_p(car(xs), str_lit("comefrom")) {
                refuse(v, str_lit("a continuation kept (comefrom): KFX has escapes, not continuations, which Rust has not"))
            } else if (sym_is_p(car(xs), str_lit("read")) || sym_is_p(car(xs), str_lit("write")) || sym_is_p(car(xs), str_lit("alloc")) || sym_is_p(car(xs), str_lit("goto"))) {
                cons(string_append(name_of(v, car(xs)), string_append(str_lit(":"), region_name(v, tvars, second(xs)))), nil())
            } else {
                refuse(v, string_append(str_lit("an effect KFX does not have: "), show_sexp(e)))
            }
        }
        _ => {
            let other = tagcase_;
            refuse(v, string_append(str_lit("an effect KFX does not have: "), show_sexp(e)))
        }
    }
}

pub fn parse_effects(v: &'static Cv, tvars: Strings, es: Sexps) -> Strings {
    if null_p(es) {
        nil()
    } else {
        effs_union(parse_effect(v, tvars, car(es)), parse_effects(v, tvars, cdr(es)))
    }
}

/// Effect atoms on region `from` made atoms on region `to`.
pub fn rename_atoms(es: Strings, from: Str, to: Str) -> Strings {
    map(lambda1(move |x: Str| {
        if string_eq_p(x, string_append(str_lit("read:"), from)) {
            string_append(str_lit("read:"), to)
        } else if string_eq_p(x, string_append(str_lit("write:"), from)) {
            string_append(str_lit("write:"), to)
        } else if string_eq_p(x, string_append(str_lit("alloc:"), from)) {
            string_append(str_lit("alloc:"), to)
        } else if string_eq_p(x, string_append(str_lit("goto:"), from)) {
            string_append(str_lit("goto:"), to)
        } else {
            x
        }
    }), es)
}

/// Effects on region `name`, made effects on the region `m` stands for.
pub fn rename_region(es: Strings, name: Str, m: &'static Ty) -> Strings {
    let tagcase_ = m;
    match *tagcase_ {
        Ty::TyMeta(k) => {
            rename_atoms(es, name, string_append(str_lit("?"), i64_to_string(k)))
        }
        Ty::TyRconst(n) => {
            rename_atoms(es, name, n)
        }
        Ty::TyVar(n) => {
            rename_atoms(es, name, n)
        }
        _ => {
            let other = tagcase_;
            es
        }
    }
}

pub fn meta_name(k: i64) -> Str {
    string_append(str_lit("?"), i64_to_string(k))
}

pub fn replace_var(name: Str, m: &'static Ty, t: &'static Ty) -> &'static Ty {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyVar(n) => {
            if string_eq_p(n, name) {
                m
            } else {
                t
            }
        }
        Ty::TyList(e, r) => {
            ty_list(replace_var(name, m, e), replace_var(name, m, r))
        }
        Ty::TyFlat(e, r) => {
            ty_flat(replace_var(name, m, e), replace_var(name, m, r))
        }
        Ty::TyShape(p, ls, ts) => {
            ty_shape(p, ls, map(lambda1(move |x: &'static Ty| {
                replace_var(name, m, x)
            }), ts))
        }
        Ty::TyTag(a, h, d, r) => {
            ty_tag(replace_var(name, m, a), replace_var(name, m, h), rename_region(d, name, m), replace_var(name, m, r))
        }
        Ty::TyData(d, args) => {
            ty_data(d, map(lambda1(move |x: &'static Ty| {
                replace_var(name, m, x)
            }), args))
        }
        Ty::TyRef(e, r) => {
            ty_ref(replace_var(name, m, e), replace_var(name, m, r))
        }
        Ty::TyProc(es, ps, r) => {
            ty_proc(rename_region(es, name, m), map(lambda1(move |p: &'static Ty| {
                replace_var(name, m, p)
            }), ps), replace_var(name, m, r))
        }
        _ => {
            let other = tagcase_;
            t
        }
    }
}

/// `t`, each of `params` replaced by its argument.
pub fn substitute(mut params: Strings, mut args: Tys, mut t: &'static Ty) -> &'static Ty {
    loop {
        if (null_p(params) || null_p(args)) {
            return t;
        } else {
            (params, args, t) = (cdr(params), cdr(args), replace_var(car(params), car(args), t));
            continue;
        }
    }
}

